/// Dangerous permission bits flagged in stable mode: `S_IWOTH` and `S_IXGRP`.
const DANGEROUS_BITS_STABLE: u64 = 0o12;
/// Dangerous permission bits flagged in preview mode: `S_IWOTH`, `S_IXGRP`, `S_IXOTH`,
/// and `S_IWGRP`.
const DANGEROUS_BITS_PREVIEW: u64 = 0o33;
/// The bits that make up a valid Unix permission mask (`0o7777`).
const VALID_BITS: u64 = 0o7777;

/// An abstract interpretation of a permission-mask expression.
///
/// Rather than requiring an exact value, we track the bits that are statically known to be
/// set (`ones`), along with whether the value is known to exceed [`u64::MAX`] (`oversized`).
/// Unknown operands (such as dynamic variables) contribute no known bits.
#[derive(Debug, Clone, Copy)]
struct KnownBits {
    /// Bits that are statically known to be set.
    ones: u64,
    /// Whether the value is known to exceed [`u64::MAX`].
    oversized: bool,
}

impl KnownBits {
    /// Nothing is known about the value.
    const UNKNOWN: Self = Self {
        ones: 0,
        oversized: false,
    };

    /// An exactly-known value.
    const fn exact(value: u64) -> Self {
        Self {
            ones: value,
            oversized: false,
        }
    }

    /// A value known to exceed [`u64::MAX`].
    const fn oversized() -> Self {
        Self {
            ones: 0,
            oversized: true,
        }
    }
}

/// Compute the [`KnownBits`] of a permission-mask expression via abstract interpretation.
fn known_bits(expr: &Expr, semantic: &SemanticModel) -> KnownBits {
    match expr {
        Expr::NumberLiteral(ast::ExprNumberLiteral {
            value: ast::Number::Int(int),
            ..
        }) => match int.as_u64() {
            Some(value) => KnownBits::exact(value),
            None => KnownBits::oversized(),
