                // is oversized if either operand is oversized.
                Operator::BitOr => KnownBits {
                    ones: left.ones | right.ones,
                    oversized: left.oversized || right.oversized,
                },
                // The known-set bits of an AND are the intersection of both operands, and the
                // value is oversized only if both operands are oversized.
                Operator::BitAnd => KnownBits {
                    ones: left.ones & right.ones,
                    oversized: left.oversized && right.oversized,
                },
